'use client'

import * as React from 'react'

import { useOffscreen } from './use-reduced-motion'
import './grid-backdrop.css'

export type GridBackdropProps = React.ComponentPropsWithoutRef<'div'> & {
    /** Line colour. */
    color?: string
    /** Colour of the glow along the horizon. */
    glowColor?: string
    /** Cell size in px. */
    cellSize?: number
    /** Seconds for the grid to travel one cell. */
    speed?: number
    paused?: boolean
}

const GridBackdrop = ({ color = 'rgba(167, 139, 250, 0.45)', glowColor = 'rgba(139, 92, 246, 0.35)', cellSize = 28, speed = 1.2, paused = false, className, style, children, ...props }: GridBackdropProps) => {
    const ref = React.useRef<HTMLDivElement | null>(null)
    const offscreen = useOffscreen(ref)

    return <div
        ref={ref}
        className={['rad-fx-grid', className].filter(Boolean).join(' ')}
        data-state={paused || offscreen ? 'paused' : 'running'}
        style={{ '--rad-fx-grid-color': color, '--rad-fx-grid-glow': glowColor, '--rad-fx-grid-size': `${cellSize}px`, '--rad-fx-grid-speed': `${speed}s`, ...style } as React.CSSProperties}
        {...props}
    >
        <div className="rad-fx-grid-plane" aria-hidden="true" />
        <div className="rad-fx-grid-content">{children}</div>
    </div>
}

export default GridBackdrop

/* GridBackdrop: a floor grid running from the horizon toward the viewer.
   The eye (perspective-origin) sits on the horizon so every line converges there.
   The floor's depth (height × sin(tilt)) must stay below the perspective distance,
   or its near edge ends up behind the camera and disappears. */
.rad-fx-grid {
    --rad-fx-grid-horizon: 38%;

    position: relative;
    isolation: isolate;
    overflow: hidden;
    perspective: 300px;
    perspective-origin: 50% var(--rad-fx-grid-horizon);
}

.rad-fx-grid-plane {
    position: absolute;
    top: var(--rad-fx-grid-horizon);
    left: -150%;
    right: -150%;
    height: 270px;
    z-index: -1;
    pointer-events: none;
    background-image:
        linear-gradient(to right, var(--rad-fx-grid-color) 1px, transparent 1px),
        linear-gradient(to bottom, var(--rad-fx-grid-color) 1px, transparent 1px);
    background-size: var(--rad-fx-grid-size, 48px) var(--rad-fx-grid-size, 48px);
    background-position: center 0;
    transform: rotateX(75deg);
    transform-origin: 50% 0;

    /* Lines dissolve into the horizon instead of ending on a hard edge. */
    mask-image: linear-gradient(to bottom, transparent 0%, #000 35%);
    animation: rad-fx-grid-travel var(--rad-fx-grid-speed, 2s) linear infinite;
}

/* Horizon fog: a soft band across the full width, densest on the horizon line. */
.rad-fx-grid::before {
    content: '';
    position: absolute;
    top: calc(var(--rad-fx-grid-horizon) - 80px);
    left: 0;
    right: 0;
    height: 160px;
    z-index: -1;
    pointer-events: none;
    background: linear-gradient(to bottom, transparent, var(--rad-fx-grid-glow, rgb(139, 92, 246, 0.35)) 50%, transparent);
}

.rad-fx-grid[data-state='paused'] .rad-fx-grid-plane { animation-play-state: paused; }

.rad-fx-grid-content { position: relative; }

@keyframes rad-fx-grid-travel {
    to { background-position: center var(--rad-fx-grid-size, 48px); }
}

@media (prefers-reduced-motion: reduce) {
    .rad-fx-grid-plane { animation: none; }
}

[data-rad-fx-motion='reduce'] .rad-fx-grid-plane { animation: none; }
